from collections import Counter

def frontier_lines(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row)
    fr=set()
    for i,row in enumerate(g):
        if len(set(row))==1 and cnt[row[0]]==W: fr.add(('r',i))
    for j in range(W):
        col={g[i][j] for i in range(H)}
        if len(col)==1 and cnt[g[0][j]]==H: fr.add(('c',j))
    return fr

def blocks(g):
    H,W=len(g),len(g[0]); fr=frontier_lines(g)
    def ranges(n,ex):
        out=[];s=None
        for i in range(n+1):
            if i not in ex and i<n and s is None: s=i
            if (i in ex or i==n) and s is not None: out.append((s,i)); s=None
        return out
    rr=ranges(H,{i for k,i in fr if k=='r'}); cc=ranges(W,{j for k,j in fr if k=='c'})
    return [(r0,c0,[row[c0:c1] for row in g[r0:r1]]) for r0,r1 in rr for c0,c1 in cc]

def transform(g):
    bl=blocks(g)
    pat=[]
    for r0,c0,b in bl:
        cnt=Counter(v for row in b for v in row)
        if len(cnt)>=2 and sorted(cnt.values())[0]>1: pat.append(b)
    if len(pat)>=2:
        A,B=pat[0],pat[1]
        shared=({v for row in A for v in row}&{v for row in B for v in row}).pop()
        marker=len({v for b in pat for row in b for v in row})
        return [[marker if A[i][j]==shared and B[i][j]==shared else shared for j in range(len(A[0]))] for i in range(len(A))]
    else:
        b=pat[0]; cnt=Counter(v for row in b for v in row)
        fill=min(cnt,key=cnt.get)
        return [[fill]*len(b[0]) for _ in b]

for n in ['1','2','3']:
    print(n, transform(G['Demo pair '+n+' input'])==G['Demo pair '+n+' output'])
print('test ok')

